    xmlXPathFreeObject(xpathObj);
    xmlXPathFreeContext(xpathCtx);

    // Clear sensitive data
    std::fill(safe_username.begin(), safe_username.end(), '\0');
    std::fill(safe_password.begin(), safe_password.end(), '\0');

